import { readFileSync } from 'node:fs'

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const PUNCT1 = new Set('+-*/%=<>!(){}[],;.'.split(''))
const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
  }
}

const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isLetter = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdPart = (c) => isIdStart(c) || isDigit(c)
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isBin = (c) => c === '0' || c === '1'
const isOct = (c) => c !== undefined && c >= '0' && c <= '7'

function scan(text) {
  const cs = Array.from(text)
  const n = cs.length
  const lines = new Array(n + 1)
  const cols = new Array(n + 1)
  let l = 1
  let c = 1
  for (let k = 0; k < n; k++) {
    lines[k] = l
    cols[k] = c
    if (cs[k] === '\n') { l++; c = 1 }
    else if (cs[k] === '\t') c = Math.floor((c - 1) / 4) * 4 + 5
    else c++
  }
  lines[n] = l
  cols[n] = c
  const fail = (k, reason) => { throw new ScanError(lines[k], cols[k], reason) }
  const tokens = []
  const add = (k, kind, body) => tokens.push(`${lines[k]}:${cols[k]} ${kind} ${body}`, kind)

  let i = 0
  while (i < n) {
    const ch = cs[i]
    if (ch === ' ' || ch === '\t' || ch === '\r' || ch === '\n') { i++; continue }
    if (ch === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') i++
      continue
    }
    if (ch === '/' && cs[i + 1] === '*') {
      const start = i
      let depth = 1
      i += 2
      while (i < n && depth > 0) {
        if (cs[i] === '/' && cs[i + 1] === '*') { depth++; i += 2 }
        else if (cs[i] === '*' && cs[i + 1] === '/') { depth--; i += 2 }
        else i++
      }
      if (depth > 0) fail(start, 'unterminated block comment')
      continue
    }
    if (ch === 'r' && cs[i + 1] === '"') {
      let j = i + 2
      while (j < n && cs[j] !== '"') j++
      if (j >= n) fail(i, 'unterminated string')
      add(i, 'rawstring', JSON.stringify(cs.slice(i + 2, j).join('')))
      i = j + 1
      continue
    }
    if (isIdStart(ch)) {
      let j = i + 1
      while (j < n && isIdPart(cs[j])) j++
      const word = cs.slice(i, j).join('')
      add(i, KEYWORDS.has(word) ? 'keyword' : 'ident', word)
      i = j
      continue
    }
    if (isDigit(ch)) {
      let j = i
      // consume a run of digits with single underscores between digits
      const run = (pred) => {
        if (!pred(cs[j])) return false
        j++
        while (j < n) {
          if (pred(cs[j])) j++
          else if (cs[j] === '_' && pred(cs[j + 1])) j += 2
          else break
        }
        return true
      }
      let bad = false
      const p = cs[i + 1]
      if (ch === '0' && p !== undefined && 'xXbBoO'.includes(p)) {
        j = i + 2
        const pred = 'xX'.includes(p) ? isHex : 'bB'.includes(p) ? isBin : isOct
        if (!run(pred)) bad = true
      } else {
        run(isDigit)
        if (cs[j] === '.' && isDigit(cs[j + 1])) { j++; run(isDigit) }
        if (cs[j] === 'e' || cs[j] === 'E') {
          if (isDigit(cs[j + 1])) { j++; run(isDigit) }
          else if ((cs[j + 1] === '+' || cs[j + 1] === '-') && isDigit(cs[j + 2])) { j += 2; run(isDigit) }
        }
      }
      if (bad || isIdPart(cs[j])) {
        while (j < n && isIdPart(cs[j])) j++
        fail(i, `invalid number ${cs.slice(i, j).join('')}`)
      }
      add(i, 'number', cs.slice(i, j).join(''))
      i = j
      continue
    }
    if (ch === '"') {
      let j = i + 1
      let out = ''
      for (;;) {
        if (j >= n) fail(i, 'unterminated string')
        const d = cs[j]
        if (d === '"') { j++; break }
        if (d === '\n') fail(j, 'newline in string')
        if (d !== '\\') { out += d; j++; continue }
        const e = cs[j + 1]
        if (e === undefined) fail(i, 'unterminated string')
        const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', 0: '\0' }
        if (Object.hasOwn(simple, e)) { out += simple[e]; j += 2; continue }
        if (e === 'x') {
          if (isHex(cs[j + 2]) && isHex(cs[j + 3])) {
            out += String.fromCodePoint(parseInt(cs[j + 2] + cs[j + 3], 16))
            j += 4
            continue
          }
        } else if (e === 'u' && cs[j + 2] === '{') {
          let k = j + 3
          while (isHex(cs[k])) k++
          if (k > j + 3 && cs[k] === '}') {
            const v = parseInt(cs.slice(j + 3, k).join(''), 16)
            if (v <= 0x10ffff) {
              out += String.fromCodePoint(v)
              j = k + 1
              continue
            }
          }
        }
        fail(j, `invalid escape \\${e}`)
      }
      add(i, 'string', JSON.stringify(out))
      i = j
      continue
    }
    const two = ch + (cs[i + 1] ?? '')
    if (PUNCT2.has(two)) { add(i, 'punct', two); i += 2; continue }
    if (PUNCT1.has(ch)) { add(i, 'punct', ch); i++; continue }
    fail(i, `unexpected character ${ch}`)
  }
  return tokens
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exit(2)
  }
  const text = readFileSync(0, 'utf8')
  let toks
  try {
    toks = scan(text)
  } catch (e) {
    if (!(e instanceof ScanError)) throw e
    process.stderr.write(`error: ${e.line}:${e.col}: ${e.message}\n`)
    process.exit(2)
  }
  let out = ''
  if (args[0] === 'tokens') {
    for (let k = 0; k < toks.length; k += 2) out += toks[k] + '\n'
  } else {
    const counts = Object.fromEntries(KINDS.map((k) => [k, 0]))
    for (let k = 1; k < toks.length; k += 2) counts[toks[k]]++
    for (const k of KINDS) out += `${k} ${counts[k]}\n`
    out += `total ${toks.length / 2}\n`
  }
  process.stdout.write(out)
}

